'use strict'
const {app,BrowserWindow,session}=require('electron'),fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{build}=require('esbuild')
const root=path.resolve(__dirname,'../..'),out=path.join(root,'qa-artifacts/image-26');fs.mkdirSync(out,{recursive:true})
app.setPath('userData',fs.mkdtempSync(path.join(out,'profile-')));app.disableHardwareAcceleration();app.on('window-all-closed',()=>{})
const wait=ms=>new Promise(r=>setTimeout(r,ms));let win
async function main(){
  await app.whenReady();session.defaultSession.webRequest.onBeforeRequest((d,cb)=>cb({cancel:/^https?:/.test(d.url)}))
  win=new BrowserWindow({show:false,width:1440,height:1000,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false,offscreen:true,backgroundThrottling:false}})
  const bundle=(await build({stdin:{contents:`import React,{useState} from 'react';import {createRoot} from 'react-dom/client';import {DesignControls,DEFAULT_DESIGN} from './src/DesignControls';function Fixture(){const [value,setValue]=useState({...DEFAULT_DESIGN});window.imageParameters=value;return <div className="design-controls-fixture composer-box"><div className="composer-actions"><DesignControls mode="generate" onModeChange={()=>{}} value={value} onChange={setValue} references={[]} onReference={()=>{}} connections={[{id:'proxy',providerId:'relay',displayName:'已有图片服务',model:'gpt-image-2.6-sunburst',baseURL:'https://relay.invalid/v1',hasApiKey:true}]}/></div></div>}createRoot(document.getElementById('root')).render(<Fixture/>);`,resolveDir:root,loader:'tsx'},bundle:true,write:false,format:'iife',loader:{'.css':'empty'},define:{'process.env.NODE_ENV':'"production"'}})).outputFiles[0].text
  const html=path.join(app.getPath('userData'),'toolbar.html');fs.writeFileSync(html,'<!doctype html><html lang="zh-CN" data-theme="light"><body><div id="root"></div></body></html>');await win.loadFile(html)
  const viewport = (width,height) => win.webContents.enableDeviceEmulation({screenPosition:'desktop',viewSize:{width,height},deviceScaleFactor:1,scale:1})
  viewport(1440,1000)
  await require('../helpers/visual-fixture.cjs')(win)
  for(const name of ['tokens.css','app.css','conversation-tools.css','design-activity.css','image-parameters.css'])await win.webContents.insertCSS(require('../helpers/read-source.cjs').readSource(path.join(root,'src/styles',name),'utf8'))
  await win.webContents.insertCSS('body{margin:0;background:var(--color-paper)}.design-controls-fixture{position:absolute;bottom:48px;left:calc((100% - min(900px,100% - 48px))/2);width:min(900px,100% - 48px)}')
  const run=script=>win.webContents.executeJavaScript(script,true),capture=async name=>{await wait(160);fs.writeFileSync(path.join(out,name+'.png'),(await win.webContents.capturePage()).toPNG())}
  await run(bundle);await wait(400)
  assert.equal(await run("document.querySelectorAll('.design-controls>details').length"),4)
  await run("document.querySelector('.p26-more>summary').click()");await wait(150)
  assert.equal(await run("document.querySelectorAll('.p26-settings-items>details').length"),7)
  const alignment=await run("[...document.querySelectorAll('.p26-settings-items>details>summary')].map(row=>({arrow:row.querySelector('svg:last-child').getBoundingClientRect().right,value:row.querySelector('.p26-setting-value,.p26-choice-value').getBoundingClientRect().right}))")
  assert(Math.max(...alignment.map(x=>x.arrow))-Math.min(...alignment.map(x=>x.arrow))<1,'settings arrows must align')
  assert(Math.max(...alignment.map(x=>x.value))-Math.min(...alignment.map(x=>x.value))<1,'settings values must align')
  await capture('settings-aligned')
  const size=await run("(()=>{const r=document.querySelector('.p26-more-panel').getBoundingClientRect();return {width:r.width,height:r.height}})()")
  const hover=async selector=>{const p=await run(`(()=>{const r=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return {x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)}})()`);win.webContents.sendInputEvent({type:'mouseMove',...p});await wait(220);return p}
  const point=await hover('.p26-complexity>summary')
  assert.equal(await run("document.querySelector('.p26-complexity>.p26-submenu').matches(':popover-open')"),true)
  assert.equal(await run("document.querySelector('.p26-complexity').dataset.side"),'right');await capture('flyout-right')
  assert.deepEqual(await run("(()=>{const r=document.querySelector('.p26-more-panel').getBoundingClientRect();return {width:r.width,height:r.height}})()"),size)
  await run("document.querySelector('.p26-complexity>summary').click()");assert.equal(await run("document.querySelector('.p26-complexity').open"),true)
  const gap=await run("Math.round(document.querySelector('.p26-more-panel').getBoundingClientRect().right+4)");win.webContents.sendInputEvent({type:'mouseMove',x:gap,y:point.y});await wait(100)
  assert.equal(await run("document.querySelector('.p26-complexity').open"),true)
  await hover('.p26-complexity .p26-choice-list');await wait(320);assert.equal(await run("document.querySelector('.p26-complexity').open"),true)
  await run("[...document.querySelectorAll('.p26-complexity button')].find(e=>e.querySelector('b')?.textContent==='低').click()");await wait(120)
  assert.equal(await run('window.imageParameters.complexity'),'low')
  await run("document.querySelector('.p26-output>summary').click()");await wait(120)
  await run("[...document.querySelectorAll('.p26-output button')].find(e=>e.querySelector('b')?.textContent==='GIF').click()");await wait(150)
  assert.equal(await run('window.imageParameters.outputFormat'),'gif');assert.equal(await run('window.imageParameters.frameCount'),9);await capture('gif-settings')
  await run("(()=>{const e=document.querySelector('[aria-label=\"动图帧数\"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(e,'12');e.dispatchEvent(new Event('input',{bubbles:true}))})()");await wait(120);assert.equal(await run('window.imageParameters.frameCount'),12)
  await run("document.querySelector('.p26-background>summary').click()");await wait(120);assert.equal(await run("[...document.querySelectorAll('.p26-background button')].find(e=>e.querySelector('b')?.textContent==='透明').disabled"),true)
  await run("document.querySelector('.p26-background>summary').focus();document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowRight',bubbles:true}))");await wait(80)
  assert.equal(await run("document.activeElement.closest('.p26-submenu')?.matches(':popover-open')"),true)
  await run("document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");assert.equal(await run("document.querySelector('.p26-background').open"),false);assert.equal(await run("document.querySelector('.p26-more').open"),true)
  await run("document.activeElement.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");assert.equal(await run("document.querySelector('.p26-more').open"),false)
  viewport(1000,900);await wait(150);await run("document.querySelector('.p26-more>summary').click()");await wait(120);await hover('.p26-complexity>summary')
  assert.equal(await run("document.querySelector('.p26-complexity').dataset.side"),'left');await capture('flyout-left')
  await run("document.documentElement.dataset.theme='dark'");await capture('flyout-dark')
  await run("document.body.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true}))");assert.equal(await run("document.querySelector('.p26-more').open"),false)
  assert.equal(await run("document.querySelectorAll(':popover-open').length"),0)
  console.log('IMAGE_26_UI_PASSED');win.destroy();app.exit(0)
}
main().catch(async e=>{console.error('IMAGE_26_UI_FAILED',e.stack);if(win&&!win.isDestroyed()){console.error(await win.webContents.executeJavaScript("JSON.stringify([...document.querySelectorAll('.design-controls details')].map(d=>({text:d.querySelector('summary').textContent,open:d.open,box:d.getBoundingClientRect().toJSON()})))"));fs.writeFileSync(path.join(out,'failed.png'),(await win.webContents.capturePage()).toPNG())}app.exit(1)})
